const moment = require("moment-timezone");

const jobCategoryInput = $input.jobcategory;
const organization = $input.organizationuid;
const customer = $input.customer_uid;
const project = $input.projectuid;
const propertyData = $input.propertydata;
const jobMasterCf = $input.jobmastercf || [];
const jobMasterCat = $input.jobmastercategory || [];

// --------------------------------------------------
// GET PROPERTY  (Loop shape: data.property = current iteration)
// --------------------------------------------------
const property =
  propertyData?.data?.property ||
  propertyData?.property ||
  propertyData?.data?.data?.property ||
  propertyData?.overall_data?.[propertyData?.current_iteration ?? 0]?.property ||
  {};

if (!property?.property_uid) {
  throw new Error("Property could not be resolved from propertyData. Check the Loop node output shape.");
}

// --------------------------------------------------
// GET PROPERTY ADDRESS
// --------------------------------------------------
const clean = v => (typeof v === "string" ? v.trim() : v);
const sourceAddress = property?.property_address || {};

const hasGeo =
  Array.isArray(sourceAddress?.geo_cordinates) &&
  sourceAddress.geo_cordinates.length === 2;

const propertyAddress = {
  landmark: clean(sourceAddress?.landmark) || "",
  city: clean(sourceAddress?.city) || "",
  state: clean(sourceAddress?.state) || "",
  street: clean(sourceAddress?.street) || clean(property?.property_name) || "",
  country: clean(sourceAddress?.country) || "United States",
  zip_code: clean(sourceAddress?.zip_code) || "",
  first_name: clean(sourceAddress?.first_name) || "",
  last_name: clean(sourceAddress?.last_name) || "",
  phone_number: clean(sourceAddress?.phone_number) || "",
  email: clean(sourceAddress?.email) || "",
  // Only send coordinates as a valid pair; otherwise omit and let Zuper geocode.
  ...(hasGeo && {
    geo_cordinates: sourceAddress.geo_cordinates,
    point_coordinates: {
      type: "Point",
      coordinates: [sourceAddress.geo_cordinates[1], sourceAddress.geo_cordinates[0]]
    }
  })
};

// --------------------------------------------------
// CUSTOM FIELDS
// --------------------------------------------------
function transformCustomFields(masterCustomFields) {
  return masterCustomFields.map(cf => ({
    label: cf.field_name,
    value: "",
    hide_to_fe: cf.hide_to_fe,
    hide_field: cf.hide_field,
    read_only: cf.read_only,
    ...(cf?.group?.group_uid &&
      cf?.group?.group_name && {
        group_uid: cf.group.group_uid,
        group_name: cf.group.group_name
      }),
    type: cf?.field_type
  }));
}
const jobCf = transformCustomFields(jobMasterCf);

// --------------------------------------------------
// JOB CATEGORY
// --------------------------------------------------
const jobCat =
  typeof jobCategoryInput === "string"
    ? jobCategoryInput
    : jobCategoryInput?.jobCat || "";

const normalizedJobCat = String(jobCat).trim().toLowerCase();

const jobCategory = jobMasterCat.find(
  c => String(c.category_name || "").trim().toLowerCase() === normalizedJobCat
);
const jobCategoryUid = jobCategory?.category_uid;

if (!jobCategoryUid) {
  throw new Error(`Job category "${jobCat}" did not match any category in jobMasterCat.`);
}

// --------------------------------------------------
// PAYLOAD
// --------------------------------------------------
const payload = {
  job: {
    job_title: `Inspection for ${propertyAddress.street || property?.property_name || ""}`,
    job_category: jobCategoryUid,
    organization: organization,
    customer: { customer_uid: customer},
    customer_address: { ...propertyAddress },
    customer_billing_address: { ...propertyAddress },
    project: project,
    property: property.property_uid,
    due_date: moment().tz($.getVariable('ZUPER_COMPANY_TIMEZONE')).add(2, "days").format("YYYY-MM-DD hh:mm:ss"),
    due_date_dt: moment().tz($.getVariable('ZUPER_COMPANY_TIMEZONE')).add(2, "days").format("YYYY-MM-DD"),
    custom_fields: jobCf
  }
};

return payload;
